#!/usr/bin/env python3
"""Compile actual private WSI target procedures with controlled opaque providers.
No emulator or hardware access. Execute the returning artifact separately on board.
"""
from pathlib import Path
import re,argparse,os,subprocess,json,hashlib
from pmf_compiler import resolve_compiler
from vulkan_state_proof_layouts import state_proof_layout,check_linked_layout
ROOT=Path(__file__).resolve().parents[1]
CONSTANTS='#VK_SUCCESS=0\n#ANVIL_VK_ERR_ARGS=-20001\n#ANVIL_VK_ERR_STATE=-20004\n#ANVIL_VK_ERR_OWNER=-20003\n#VK_SURFACE_TRANSFORM_IDENTITY_BIT_KHR=1\n#VK_COMPOSITE_ALPHA_OPAQUE_BIT_KHR=1\n#VK_IMAGE_USAGE_COLOR_ATTACHMENT_BIT=16\n#VK_IMAGE_USAGE_TRANSFER_SRC_BIT=1\n#VK_FORMAT_B8G8R8A8_UNORM=44\n#VK_COLOR_SPACE_SRGB_NONLINEAR_KHR=0\n#VK_PRESENT_MODE_FIFO_KHR=2\n#VK_SHARING_MODE_EXCLUSIVE=0\n'
PROVIDERS='Global failAt.i, calls.i, acquired.i, wrongKey.i, seenW.i, seenH.i\nProcedure ProbeStep(n.i) : calls=calls*10+n : EndProcedure\nProcedure.i avkWsiProviderRegister(*p.AnvilVkWsiProviderInfo,*out)\n ProbeStep(1) : seenW=*p\\capabilities\\currentWidth : seenH=*p\\capabilities\\currentHeight\n If failAt=1 : ProcedureReturn -81 : EndIf\n PokeI(*out,101) : ProcedureReturn 0\nEndProcedure\nProcedure.i avkWsiSurfaceCreate(instance.i,provider.i,key.i,*out)\n ProbeStep(2) : If failAt=2 : ProcedureReturn -82 : EndIf\n PokeI(*out,202) : ProcedureReturn 0\nEndProcedure\nProcedure.i avkWsiSwapchainCreate(device.i,*p.AnvilVkWsiSwapchainInfo,*out)\n ProbeStep(3) : If failAt=3 : ProcedureReturn -83 : EndIf\n If PeekI(*p\\providerImages)<>404 Or *p\\providerImageCount<>1 Or *p\\presentMode<>2 : ProcedureReturn -90 : EndIf\n PokeI(*out,303) : ProcedureReturn 0\nEndProcedure\nProcedure.i avkWsiSwapchainDestroy(device.i,chain.i)\n ProbeStep(4) : If failAt=4 Or acquired<>0 : ProcedureReturn -84 : EndIf\n ProcedureReturn 0\nEndProcedure\nProcedure.i avkWsiSurfaceDestroy(instance.i,surface.i)\n ProbeStep(5) : If failAt=5 : ProcedureReturn -85 : EndIf\n ProcedureReturn 0\nEndProcedure\nProcedure.i avkWsiProviderDestroy(provider.i)\n ProbeStep(6) : If failAt=6 : ProcedureReturn -86 : EndIf\n ProcedureReturn 0\nEndProcedure\nProcedure.i avkWsiAcquire(device.i,chain.i,timeout.i,*out)\n ProbeStep(7) : If failAt=7 : ProcedureReturn 1 : EndIf\n acquired=1 : PokeL(*out,0) : ProcedureReturn 0\nEndProcedure\nProcedure.i avkWsiImageKey(device.i,chain.i,index.i)\n ProbeStep(8) : If wrongKey<>0 : ProcedureReturn 405 : EndIf\n ProcedureReturn 404\nEndProcedure\nProcedure.i NeonVkChromeWsiAttach(device.i,chain.i,index.i)\n ProbeStep(9) : If failAt=9 Or failAt=10 : ProcedureReturn -89 : EndIf\n ProcedureReturn 0\nEndProcedure\nProcedure.i avkWsiReleaseImage(device.i,chain.i,index.i)\n ProbeStep(0) : If failAt=10 : ProcedureReturn -80 : EndIf\n acquired=0 : ProcedureReturn 0\nEndProcedure\n'
CASES='Global target.NeonVkPresentTarget\nProcedure Reset(populated.i)\n failAt=0 : calls=0 : acquired=0 : wrongKey=0 : seenW=0 : seenH=0\n target\\provider=0 : target\\surface=0 : target\\swapchain=0 : target\\image=0\n If populated<>0 : target\\provider=101 : target\\surface=202 : target\\swapchain=303 : target\\image=404 : EndIf\nEndProcedure\nProcedure Record(id.i,rc.i)\n Define at.i : at=#TC_REPORT+64+(id-1)*80\n PokeI(at,id) : PokeI(at+8,rc) : PokeI(at+16,target\\provider) : PokeI(at+24,target\\surface)\n PokeI(at+32,target\\swapchain) : PokeI(at+40,target\\image) : PokeI(at+48,calls)\n PokeI(at+56,acquired) : PokeI(at+64,seenW) : PokeI(at+72,seenH)\nEndProcedure\nProcedure.i Main(services.i)\n Define rc.i,i.i\n For i=0 To 4095 : PokeA(#TC_REPORT+i,0) : Next\n Reset(0) : rc=NeonVkPresentTargetCreate(11,22,404,505,800,1280,@target) : Record(1,rc)\n Reset(0) : failAt=1 : rc=NeonVkPresentTargetCreate(11,22,404,505,800,1280,@target) : Record(2,rc)\n Reset(0) : failAt=2 : rc=NeonVkPresentTargetCreate(11,22,404,505,800,1280,@target) : Record(3,rc)\n Reset(0) : failAt=3 : rc=NeonVkPresentTargetCreate(11,22,404,505,800,1280,@target) : Record(4,rc)\n Reset(1) : rc=NeonVkPresentTargetDestroy(11,22,@target) : Record(5,rc)\n Reset(1) : failAt=4 : rc=NeonVkPresentTargetDestroy(11,22,@target) : Record(6,rc)\n Reset(1) : failAt=5 : rc=NeonVkPresentTargetDestroy(11,22,@target) : Record(7,rc)\n Reset(1) : failAt=6 : rc=NeonVkPresentTargetDestroy(11,22,@target) : Record(8,rc)\n Reset(1) : rc=NeonVkPresentTargetAcquire(22,404,@target) : Record(9,rc)\n Reset(1) : failAt=7 : rc=NeonVkPresentTargetAcquire(22,404,@target) : Record(10,rc)\n Reset(1) : rc=NeonVkPresentTargetAcquire(22,405,@target) : Record(11,rc)\n Reset(1) : wrongKey=1 : rc=NeonVkPresentTargetAcquire(22,404,@target) : Record(12,rc)\n Reset(1) : failAt=9 : rc=NeonVkPresentTargetAcquire(22,404,@target) : Record(13,rc)\n Reset(1) : failAt=10 : rc=NeonVkPresentTargetAcquire(22,404,@target) : Record(14,rc)\n calls=0 : rc=NeonVkPresentTargetDestroy(11,22,@target) : Record(15,rc)\n Reset(1) : rc=NeonVkPresentTargetCreate(11,22,404,505,800,1280,@target) : Record(16,rc)\n Reset(0) : rc=NeonVkPresentTargetCreate(11,22,404,505,0,1280,@target) : Record(17,rc)\n PokeI(#TC_REPORT,$57535450) : PokeI(#TC_REPORT+8,0) : PokeI(#TC_REPORT+16,17) : PokeI(#TC_REPORT+24,10)\n ProcedureReturn 0\nEndProcedure\n'

def source(root=ROOT):
 wsi=(root/'Anvil/Graphics/Vulkan/vk_wsi.pbi').read_text(encoding='utf8')
 helper=(root/'Anvil/Graphics/Vulkan/neon_vk_present_target.pbi').read_text(encoding='utf8')
 structs='\n'.join(re.search(r'^Structure '+n+r'\b.*?^EndStructure',wsi,re.M|re.S).group() for n in ['AnvilVkWsiCapabilities','AnvilVkWsiFormat','AnvilVkWsiProviderInfo','AnvilVkWsiSwapchainInfo'])
 return CONSTANTS+structs+'\n'+PROVIDERS+helper.replace('XIncludeFile "Anvil/Graphics/Vulkan/neon_vk_chrome.pbi"','')+'\n'+CASES

def main():
 ap=argparse.ArgumentParser(description=__doc__);ap.add_argument('--compiler',required=True);ap.add_argument('--target',choices=['pi4','pi3','unoq','rockpi4c'],required=True);ap.add_argument('--out',type=Path,required=True);a=ap.parse_args()
 d=a.out.resolve();d.mkdir(parents=True,exist_ok=False);layout=state_proof_layout(a.target)
 (d/'proof.pbi').write_text('#TC_REPORT='+str(layout['report'])+'\n'+source(),encoding='utf8')
 env=os.environ.copy();env['PMF_ROOT']=str(ROOT)
 q=subprocess.run([str(resolve_compiler(a.compiler)),'--compile',str(d/'proof.pbi'),'-t',a.target,'--load-addr',hex(layout['load']),'--stack-addr',hex(layout['stack']),'--entry-returns','--wants-services','-o',str(d/'proof.img')],env=env,capture_output=True,text=True,encoding='utf8',timeout=120)
 (d/'compile.txt').write_text(q.stdout+q.stderr,encoding='utf8');print(q.stdout+q.stderr);assert q.returncode==0
 ranges=check_linked_layout(layout,q.stdout+q.stderr);p=d/'proof.img.pmf'
 i=dict(bytes=p.stat().st_size,sha256=hashlib.sha256(p.read_bytes()).hexdigest(),layout=layout,checked_ranges=ranges,executed=False,controlled_providers=True,source_hashes={n:hashlib.sha256((ROOT/n).read_bytes()).hexdigest() for n in ['Anvil/Graphics/Vulkan/neon_vk_present_target.pbi','Anvil/Graphics/Vulkan/vk_wsi.pbi']})
 (d/'identity.json').write_text(json.dumps(i,indent=2),encoding='utf8')
if __name__=='__main__':main()
